import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { API_CONFIG } from '../config/api.config';
import { DownloadFile, SharedFile } from '../models/file';
import { ShareOptions, ShareResult } from '../models/share';

interface FileMetadata {
  id: string;
  name: string;
  size: number;
  expirationDate: string;
  linkStatus: 'active' | 'expired';
  downloadLink: string;
}

interface ShareMetadata {
  name: string;
  mimeType: string;
  size: number;
  expirationDate: string;
  passwordRequired: boolean;
}

@Injectable({ providedIn: 'root' })
export class FileService {
  readonly maxUploadSizeBytes = API_CONFIG.maxUploadSizeBytes;
  readonly acceptedFileTypes = API_CONFIG.acceptedFileTypes;

  constructor(private readonly http: HttpClient) {}

  async upload(file: File, options: ShareOptions): Promise<ShareResult> {
    const form = new FormData();
    form.append('file', file, file.name);
    if (options.password) form.append('password', options.password);
    form.append('expirationDays', options.expiration);
    const response = await firstValueFrom(this.http.post<{ metadata: FileMetadata }>(
      `${API_CONFIG.baseUrl}/files`, form));
    return {
      link: this.toFrontendDownloadLink(response.metadata.downloadLink),
      expiresAt: new Date(response.metadata.expirationDate),
    };
  }

  async list(): Promise<SharedFile[]> {
    const response = await firstValueFrom(this.http.get<FileMetadata[]>(`${API_CONFIG.baseUrl}/files`));
    return response.map(metadata => this.toSharedFile(metadata));
  }

  async getDownload(token: string): Promise<DownloadFile> {
    const metadata = await firstValueFrom(this.http.get<ShareMetadata>(
      `${API_CONFIG.baseUrl}/shares/${encodeURIComponent(token)}`));
    return {
      id: token,
      token,
      name: metadata.name,
      size: metadata.size,
      expiresAt: this.formatDate(metadata.expirationDate),
      status: new Date(metadata.expirationDate) > new Date() ? 'active' : 'expired',
      protected: metadata.passwordRequired,
    };
  }

  async download(token: string, password: string): Promise<Blob> {
    return await firstValueFrom(this.http.post(
      `${API_CONFIG.baseUrl}/shares/${encodeURIComponent(token)}/download`,
      { password }, { responseType: 'blob' }));
  }

  async remove(id: string): Promise<void> {
    await firstValueFrom(this.http.delete(`${API_CONFIG.baseUrl}/files/${encodeURIComponent(id)}`));
  }

  formatSize(bytes: number): string {
    return `${(bytes / 1_000_000).toLocaleString('fr-FR', { maximumFractionDigits: 2 })} Mo`;
  }

  private toSharedFile(metadata: FileMetadata): SharedFile {
    return {
      id: metadata.id,
      token: metadata.downloadLink.split('/').pop() ?? metadata.id,
      name: metadata.name,
      size: metadata.size,
      expiresAt: metadata.expirationDate,
      status: metadata.linkStatus,
    };
  }

  private toFrontendDownloadLink(downloadLink: string): string {
    const token = decodeURIComponent(downloadLink.split('/').pop() ?? downloadLink);
    return `${window.location.origin}/download/${encodeURIComponent(token)}`;
  }

  private formatDate(value: string): string {
    return new Date(value).toLocaleDateString('fr-FR');
  }
}

import { Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { API_CONFIG } from '../../core/config/api.config';
import { FileService } from '../../core/service/file.service';
import { SiteHeaderComponent } from '../../shared/components/site-header/site-header.component';

@Component({ selector: 'app-upload-file', standalone: true, imports: [FormsModule, SiteHeaderComponent], templateUrl: './upload-file.component.html', styleUrl: './upload-file.component.scss' })
export class UploadFileComponent {
  file = signal<File | null>(null); uploading = signal(false); complete = signal(false); error = signal(''); link = signal(''); password = ''; expiration = '1'; dragActive = signal(false);
  readonly acceptedTypes = API_CONFIG.acceptedFileTypes;
  constructor(readonly files: FileService) {}
  choose(event: Event): void { const selected = (event.target as HTMLInputElement).files?.[0]; if (selected) this.select(selected); }
  drop(event: DragEvent): void { event.preventDefault(); this.dragActive.set(false); const dropped = event.dataTransfer?.files[0]; if (dropped) this.select(dropped); }
  select(value: File): void { this.error.set(value.size > this.files.maxUploadSizeBytes ? 'La taille maximale autorisée est de 1 Go.' : ''); if (!this.error()) { this.file.set(value); this.complete.set(false); } }
  remove(): void { this.file.set(null); this.complete.set(false); this.link.set(''); }
  async upload(): Promise<void> { if (!this.file()) { this.error.set('Choisissez un fichier avant de continuer.'); return; } this.uploading.set(true); this.error.set(''); try { const result = await this.files.upload(this.file()!, { password: this.password, expiration: this.expiration as '1' | '7' }); this.link.set(result.link); this.complete.set(true); } catch (error) { this.error.set((error as { error?: { message?: string } })?.error?.message ?? 'Impossible de téléverser le fichier.'); } finally { this.uploading.set(false); } }
  copy(): void { void navigator.clipboard?.writeText(this.link()); }
}
<div class="page">
  <app-site-header />
  <main>
    <section class="upload-card" [class.empty]="!file()" [class.dragging]="dragActive()"
      (dragover)="$event.preventDefault(); dragActive.set(true)" (dragleave)="dragActive.set(false)" (drop)="drop($event)">
      @if (!file()) {
        <h1>Tu veux partager un fichier ?</h1>
        <button class="upload-trigger" type="button" aria-label="Choisir un fichier à partager" (click)="uploadInput.click()">
          <span class="upload-icon">
            <svg width="48" height="48" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M12 21v-9m0 0-4 4m4-4 4 4M20.88 18.09A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.29" />
            </svg>
          </span>
        </button>
        <input #uploadInput id="upload-input" type="file" [accept]="acceptedTypes" (change)="choose($event)" />
      } @else {
        <h1>Ajouter un fichier</h1>
        <div class="file-row">
          <span class="file-icon" aria-hidden="true">▧</span>
          <span class="file-name" [title]="file()!.name">{{ file()!.name }}<small>{{ files.formatSize(file()!.size) }}</small></span>
          <button class="outline" type="button" (click)="remove()">Retirer</button>
        </div>
        @if (complete()) {
          <p class="success" role="status">Félicitations, ton fichier serait conservé.</p>
          <a class="share-link" [href]="link()">{{ link() }}</a>
          <button class="secondary" type="button" (click)="copy()">Copier le lien</button>
        } @else {
          <label for="password">Mot de passe</label>
          <input id="password" type="password" [(ngModel)]="password" placeholder="Optionnel" autocomplete="new-password" />
          <label for="expiration">Expiration</label>
          <select id="expiration" [(ngModel)]="expiration">
            <option value="1">Une journée</option>
            <option value="7">Une semaine</option>
          </select>
          <button class="secondary" type="button" [disabled]="uploading()" (click)="upload()">{{ uploading() ? 'Téléversement…' : 'Téléverser' }}</button>
        }
      }
      @if (error()) { <p class="error" role="alert">{{ error() }}</p> }
    </section>
  </main>
  <footer>Copyright DataShare<sup>©</sup> 2025</footer>
</div>

import { Component, OnInit, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { FileService } from '../../core/service/file.service';
import { DownloadFile } from '../../core/models/file';
import { SiteHeaderComponent } from '../../shared/components/site-header/site-header.component';

@Component({
  selector: 'app-download-file',
  standalone: true,
  imports: [FormsModule, SiteHeaderComponent],
  templateUrl: './download-file.component.html',
  styleUrl: './download-file.component.scss',
})
export class DownloadFileComponent implements OnInit {
  loading = signal(true);
  file = signal<DownloadFile | null>(null);
  error = signal('');
  password = '';

  constructor(private readonly route: ActivatedRoute, readonly files: FileService) {}

  async ngOnInit(): Promise<void> {
    try {
      this.file.set(await this.files.getDownload(this.route.snapshot.paramMap.get('token') ?? ''));
    } catch {
      this.error.set('Ce fichier est introuvable ou le lien a expiré.');
    } finally {
      this.loading.set(false);
    }
  }

  canDownload(): boolean {
    const file = this.file();
    return !!file && file.status === 'active' && (!file.protected || this.password.length > 0);
  }

  download(): void {
    const file = this.file();
    if (!file || !this.canDownload()) return;

    void this.files.download(file.token, this.password).then(blob => {
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = file.name;
      anchor.click();
      URL.revokeObjectURL(url);
    }).catch(() => this.error.set('Mot de passe incorrect ou téléchargement impossible.'));
  }
}
<div class="page">
  <app-site-header />

  <main>
    <section class="card download-card" aria-labelledby="download-title"
      [class.message-card]="loading() || error() || file()?.status === 'expired'">
      @if (loading()) {
        <p class="loading" role="status">Chargement…</p>
      } @else {
        <h1 id="download-title">Télécharger un fichier</h1>
        @if (error() || file()?.status === 'expired') {
          <p class="notice notice-error" role="alert">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="m7.86 2-5.73 5.73v8.54L7.86 22h8.28l5.73-5.73V7.73L16.14 2ZM12 8v4m0 4h.01" />
            </svg>
            <span>{{ error() || "Ce fichier n'est plus disponible en téléchargement car il a expiré." }}</span>
          </p>
        } @else if (file()) {
          <div class="file-row">
            <svg class="file-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M14 3H4v18h16V9l-6-6ZM14 3v6h6" />
              <path d="m8 17 3-4 5 6H8Z" fill="currentColor" stroke="none" />
              <circle cx="8" cy="9" r="1.5" fill="currentColor" stroke="none" />
            </svg>
            <div class="file-details">
              <span class="file-name" [title]="file()!.name">{{ file()!.name }}</span>
              <small>{{ files.formatSize(file()!.size) }}</small>
            </div>
          </div>

          <p class="notice" [class.notice-warning]="file()!.expiresAt === 'demain'" role="status">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              @if (file()!.expiresAt === 'demain') {
                <path d="m10.3 3.9-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.1l-8-14a2 2 0 0 0-3.4 0ZM12 9v4m0 4h.01" />
              } @else {
                <circle cx="12" cy="12" r="10" />
                <path d="M12 11v6m0-10h.01" />
              }
            </svg>
            <span>Ce fichier expirera {{ file()!.expiresAt }}.</span>
          </p>

          @if (file()!.protected) {
            <label for="download-password">Mot de passe</label>
            <input id="download-password" type="password" [(ngModel)]="password"
              placeholder="Saisissez le mot de passe..." autocomplete="current-password"
              (keydown.enter)="download()" />
          }

          <button class="submit download-button" type="button" [disabled]="!canDownload()" (click)="download()">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M12 13v8m-4-4 4 4 4-4M20.88 18.09A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.29" />
            </svg>
            Télécharger
          </button>
        }
      }
    </section>
  </main>

  <footer>Copyright DataShare<sup>©</sup> 2025</footer>
</div>

import { Component, signal } from '@angular/core';
import { AbstractControl, FormBuilder, ReactiveFormsModule, ValidationErrors, Validators } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../core/service/auth.service';
import { SiteHeaderComponent } from '../../shared/components/site-header/site-header.component';
function matches(control: AbstractControl): ValidationErrors|null { return control.value === control.parent?.get('password')?.value ? null : { mismatch:true }; }
@Component({ selector:'app-register', standalone:true, imports:[ReactiveFormsModule,RouterLink,SiteHeaderComponent], templateUrl:'./register.component.html', styleUrl:'./register.component.scss' })
export class RegisterComponent { submitted=signal(false); confirmation=signal(''); form; constructor(private readonly fb:FormBuilder,readonly auth:AuthService,private readonly router:Router){this.form=this.fb.nonNullable.group({email:['',[Validators.required,Validators.email]],password:['',Validators.required],confirmPassword:['',[Validators.required,matches]]});} async submit():Promise<void>{this.submitted.set(true);this.confirmation.set('');if(this.form.invalid)return;const ok=await this.auth.register(this.form.controls.email.value,this.form.controls.password.value);if(ok){this.confirmation.set('Compte créé. Vous pouvez maintenant vous connecter.');setTimeout(()=>void this.router.navigateByUrl('/login'),1000);}} }
<div class="page">
  <app-site-header />

  <main>
    <section class="card" aria-labelledby="register-title">
      <h1 id="register-title">Créer un compte</h1>
      <form [formGroup]="form" (ngSubmit)="submit()" novalidate>
        <div class="field">
          <label for="register-email">Email</label>
          <input id="register-email" type="email" formControlName="email" placeholder="Saisissez votre email..."
            autocomplete="email" [attr.aria-invalid]="submitted() && form.controls.email.invalid"
